describe('Search Bar Expansion on Focus', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Set viewport to mobile size
    });

    it('should expand the search bar on focus', () => {
        cy.get('.search-bar') // Replace with the actual selector for the search bar
            .focus()
            .should('have.class', 'expanded'); // Replace with the actual class that indicates expansion
    });

    it('should not expand the search bar if already expanded', () => {
        cy.get('.search-bar') // Replace with the actual selector for the search bar
            .focus()
            .should('have.class', 'expanded'); // Ensure it expands first
        cy.get('.search-bar') // Focus again to check edge case
            .focus()
            .should('have.class', 'expanded'); // Should remain expanded
    });
});
